26	
27	    /** Orders bridges deterministically by smaller endpoint, larger endpoint, then id. */
28	    private static final Comparator<Graph.Edge> BRIDGE_ORDER = Comparator
29	            .comparingInt((Graph.Edge e) -> Math.min(e.u(), e.v()))
30	            .thenComparingInt(e -> Math.max(e.u(), e.v()))
31	            .thenComparingInt(Graph.Edge::id);
32	
33	    /**
34	     * Analyzes the given graph's connectivity.
35	     *
36	     * @param graph the graph to analyze
37	     * @return its articulation points and bridges
38	     */
39	    public ConnectivityResult analyze(Graph graph) {
40	        return new Search(graph).run();
41	    }
42	
43	    /**
44	     * Holds the mutable depth-first-search state for a single
45	     * {@link #analyze(Graph)} invocation, keeping {@link GraphConnectivity}
46	     * itself stateless.
47	     */
48	    private static final class Search {
49	
50	        private final Graph graph;
51	        private final LowLinkState state;
52	        private final boolean[] isArticulationPoint;
53	        private final List<Graph.Edge> bridges = new ArrayList<>();
54	
55	        Search(Graph graph) {
56	            int vertexCount = graph.vertexCount();
57	            this.graph = graph;
58	            this.state = new LowLinkState(vertexCount);
59	            this.isArticulationPoint = new boolean[vertexCount];
60	        }
61	
62	        ConnectivityResult run() {
63	            int vertexCount = graph.vertexCount();
64	            for (int u = 0; u < vertexCount; u++) {
65	                if (!state.isDiscovered(u)) {
66	                    explore(u);
67	                }
68	            }
69	
70	            List<Integer> articulationPoints = new ArrayList<>();
71	            for (int u = 0; u < vertexCount; u++) {
72	                if (isArticulationPoint[u]) {
73	                    articulationPoints.add(u);
74	                }
75	            }
76	            bridges.sort(BRIDGE_ORDER);
77	            return new ConnectivityResult(
78	                    List.copyOf(articulationPoints), List.copyOf(bridges));
79	        }
80	
81	        /**
82	         * Explores the DFS tree rooted at {@code root} using an explicit stack.
83	         *
84	         * <p>The stack always holds the current root-to-node path, which lets each
85	         * vertex fold its low-link, cut-vertex verdict, and the bridge status of its
86	         * incoming edge into its parent the moment it is fully explored — the
87	         * iterative equivalent of returning from a recursive call.
88	         */
89	        private void explore(int root) {
90	            state.discover(root);
91	
92	            Deque<Frame> stack = new ArrayDeque<>();
93	            stack.push(new Frame(root, null));
94	
95	            while (!stack.isEmpty()) {
96	                Frame frame = stack.peek();
97	                int u = frame.vertex;
98	                List<Graph.Edge> incident = graph.incidentEdges(u);
99	
100	                if (frame.nextEdge < incident.size()) {
101	                    Graph.Edge edge = incident.get(frame.nextEdge++);
102	                    int v = edge.other(u);
103	                    if (v == u) {
104	                        // Self-loop: irrelevant to articulation points and bridges.
105	                        continue;
106	                    }
107	                    if (!state.isDiscovered(v)) {
108	                        frame.children++;
109	                        state.discover(v);
110	                        stack.push(new Frame(v, edge));
111	                    } else if (!edge.equals(frame.parentEdge)) {
112	                        // Back edge — but skip only the single tree edge we arrived on.
113	                        // A parallel edge to the parent has a different id, so it counts.
114	                        state.relaxAgainstAncestor(u, v);
115	                    }
116	                } else {
117	                    // u is fully explored; fold its result into its parent.
118	                    stack.pop();
119	                    foldIntoParent(u, frame, stack.peek());
120	                }
121	            }
122	        }
