126	         * root becomes a cut vertex with more than one child, while any other vertex
127	         * propagates its low-link upward, may mark its parent as a cut vertex, and may
128	         * mark its incoming tree edge as a bridge.
129	         *
130	         * @param u           the vertex that has just finished exploring
131	         * @param frame       {@code u}'s traversal frame
132	         * @param parentFrame the frame of {@code u}'s parent, or {@code null} if
133	         *                    {@code u} is the DFS root
134	         */
135	        private void foldIntoParent(int u, Frame frame, Frame parentFrame) {
136	            Graph.Edge incoming = frame.parentEdge;
137	            if (incoming == null) {
138	                // The DFS root is a cut vertex only if it has more than one DFS child.
139	                if (frame.children > 1) {
140	                    isArticulationPoint[u] = true;
141	                }
142	                return;
143	            }
144	
145	            int parent = incoming.other(u);
146	            state.propagateFromChild(parent, u);
147	
148	            // The incoming tree edge is a bridge when u's subtree has no back edge
149	            // reaching the parent or above (strict inequality, so a parallel edge
150	            // back to the parent disqualifies it).
151	            if (state.low(u) > state.discovery(parent)) {
152	                bridges.add(incoming);
153	            }
154	
155	            // A non-root vertex is a cut vertex when one of its children's subtrees
156	            // cannot reach above it via a back edge.
157	            boolean parentIsRoot = parentFrame.parentEdge == null;
158	            if (!parentIsRoot && state.low(u) >= state.discovery(parent)) {
159	                isArticulationPoint[parent] = true;
160	            }
161	        }
162	    }
163	
