import java.util.*;
public class Oracle {
  static int components(int V,int[][] edges,int rmV,int rmE){
    List<List<Integer>> adj=new ArrayList<>(); for(int i=0;i<V;i++) adj.add(new ArrayList<>());
    for(int i=0;i<edges.length;i++){ if(i==rmE) continue; int a=edges[i][0],b=edges[i][1];
      if(a==rmV||b==rmV) continue; adj.get(a).add(b); adj.get(b).add(a); }
    boolean[] seen=new boolean[V]; int c=0;
    for(int s=0;s<V;s++){ if(s==rmV||seen[s]) continue; c++; Deque<Integer> st=new ArrayDeque<>(); st.push(s); seen[s]=true;
      while(!st.isEmpty()){int u=st.pop(); for(int w:adj.get(u)) if(!seen[w]&&w!=rmV){seen[w]=true;st.push(w);}}}
    return c; }
  static Set<Integer> bAP(int V,int[][] e){int base=components(V,e,-1,-1); Set<Integer> s=new TreeSet<>();
    for(int v=0;v<V;v++) if(components(V,e,v,-1)>base) s.add(v); return s;}
  static Set<String> bBr(int V,int[][] e){int base=components(V,e,-1,-1); Set<String> s=new TreeSet<>();
    for(int i=0;i<e.length;i++){ if(e[i][0]==e[i][1]) continue; if(components(V,e,-1,i)>base)
      s.add(Math.min(e[i][0],e[i][1])+"-"+Math.max(e[i][0],e[i][1])); } return s;}
  public static void main(String[] a){
    Random r=new Random(7); int trials=200000, apM=0, brM=0, par=0;
    for(int t=0;t<trials;t++){ int V=2+r.nextInt(6); int E=r.nextInt(2*V+1);
      int[][] e=new int[E][2]; Map<String,Integer> seen=new HashMap<>(); boolean p=false;
      for(int i=0;i<E;i++){ int u=r.nextInt(V),v=r.nextInt(V); e[i]=new int[]{u,v};
        if(u!=v){String k=Math.min(u,v)+"-"+Math.max(u,v); if(seen.merge(k,1,Integer::sum)>1) p=true;} }
      if(p) par++;
      ConnectivityResult res=new GraphConnectivity().analyze(UndirectedGraph.fromEdges(V,e));
      Set<Integer> ap=new TreeSet<>(res.articulationPoints());
      Set<String> br=new TreeSet<>(); for(Edge g:res.bridges()) br.add(Math.min(g.u(),g.v())+"-"+Math.max(g.u(),g.v()));
      if(!ap.equals(bAP(V,e))) apM++; if(!br.equals(bBr(V,e))) brM++; }
    System.out.println("UNDIRECTED trials="+trials+" withParallel="+par+" apMismatches="+apM+" bridgeMismatches="+brM); }
}
