import java.util.*;
public class SccOracle {
  static boolean[] reach(int V,int[][] e,int s){ List<List<Integer>> adj=new ArrayList<>();
    for(int i=0;i<V;i++) adj.add(new ArrayList<>()); for(int[] a:e) adj.get(a[0]).add(a[1]);
    boolean[] r=new boolean[V]; Deque<Integer> st=new ArrayDeque<>(); st.push(s); r[s]=true;
    while(!st.isEmpty()){int u=st.pop(); for(int w:adj.get(u)) if(!r[w]){r[w]=true;st.push(w);}} return r;}
  static Set<List<Integer>> brute(int V,int[][] e){ boolean[][] R=new boolean[V][]; for(int i=0;i<V;i++) R[i]=reach(V,e,i);
    int[] c=new int[V]; Arrays.fill(c,-1); int n=0; for(int i=0;i<V;i++){ if(c[i]!=-1) continue; c[i]=n;
      for(int j=i+1;j<V;j++) if(c[j]==-1&&R[i][j]&&R[j][i]) c[j]=n; n++; }
    Map<Integer,List<Integer>> m=new TreeMap<>(); for(int i=0;i<V;i++) m.computeIfAbsent(c[i],k->new ArrayList<>()).add(i);
    Set<List<Integer>> s=new HashSet<>(); for(List<Integer> g:m.values()){Collections.sort(g); s.add(g);} return s;}
  public static void main(String[] a){ Random r=new Random(11); int trials=200000, miss=0, par=0;
    for(int t=0;t<trials;t++){ int V=1+r.nextInt(7); int E=r.nextInt(3*V+1); int[][] e=new int[E][2];
      Set<String> seen=new HashSet<>(); boolean p=false;
      for(int i=0;i<E;i++){ int u=r.nextInt(V),v=r.nextInt(V); e[i]=new int[]{u,v}; if(!seen.add(u+">"+v)) p=true; }
      if(p) par++;
      Set<List<Integer>> got=new HashSet<>(new StronglyConnectedComponents().find(DirectedGraph.fromEdges(V,e)));
      if(!got.equals(brute(V,e))) miss++; }
    System.out.println("SCC trials="+trials+" withParallelArcs="+par+" mismatches="+miss); }
}
